catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    g_form.hideFieldMsg('telework_start_date', true);
    g_form.hideFieldMsg('telework_end_date', true);

    var msg = "";

    //debugger;

    // Check End Date is in last year, current year, or next year but not later or earlier. Also in same year as start date.
    var endDate = g_form.getValue('telework_end_date');
    var startDate = g_form.getValue("telework_start_date");

    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMTelWrkUtils');
    ga.addParam('sysparm_name', 'checkDateYear');
    ga.addParam('sysparm_date_to_check', endDate);
    ga.addParam('sysparm_other_date', startDate);
    ga.addParam('sysparm_is_start', "false");
    ga.getXMLAnswer(resultDateYear);

    // GlideAjax callback function
    function resultDateYear(answer) {
        var resultsObj = JSON.parse(answer);

        if (resultsObj.goodYear === "false") {
            msg = getMessage('x_hccc_hoc_ohs.telework_end_date_year_bad');
            g_form.showFieldMsg('telework_end_date', msg, 'error');
        } else if (resultsObj.endDate != "") {
            //msg = getMessage('x_hccc_hoc_ohs.telework_end_date_same_year_start');
            //g_form.addInfoMessage(msg);
            g_form.setValue('telework_end_date', resultsObj.endDate);
        }

        // If Start Date is empty, skip comparing dates
        startDate = g_form.getValue("telework_start_date");
        endDate = g_form.getValue('telework_end_date');
        if (startDate != "") {

            // Get date format used
            var format = g_user_date_format;

            // If new value for Start date is after End date, show error message
            // 1 (true) if start is greater than end
            // 0 if end is greater than start of if they are the same
            // -1 if either of the dates is in an invalid format
            var isEndBeforeStart = compareDates(startDate, format, endDate, format);
            if (isEndBeforeStart) {
                msg = getMessage('x_hccc_hoc_ohs.end_date_after_start_date');
                g_form.showFieldMsg('telework_end_date', msg, 'error');
                //return;
            }
        }

    }

}
